 s=S[n];r={'code_id':s['code_id'],'source_id':s['source_id'],'source_sha256':s['source_sha256'],'number':s['number'],'status':'retained_unchanged' if text is None else 'rewrite_draft','proposed_xml':text,'reason':reason,'review_notes':notes,'benefit_review':benefit,'substantive_impact':{'version':1,'classification':classification,'assessment':reason+' Le bilan porte sur le dispositif précis ; un article ou un renvoi n’est pas compté comme une nouvelle simplification.','scope_limitations':'Pas de réduction de taxe, de délai d’instruction ou de coût national chiffrée. Les exigences de sécurité, environnement, patrimoine et droits privés demeurent dans leur champ ; les textes et modèles hors du lot sont identifiés dans l’audit.','new_burdens_review':'Aucune déclaration, attestation ni autorisation supplémentaire n’est instituée. Les fusions de supports conservent les informations nécessaires et peuvent demander leur présentation lisible sur le document commun ; leur coût net n’est pas établi. Le réemploi déjà garanti par le CRPA n’est pas une nouvelle suppression nette.','effects':effects}}
